<script setup>
import {reactive,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {createCurationApi,validCurationBody} from '../../services/experience-curations.js'
import {createCurationRecovery} from '../../services/curation-recovery.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {priceLocalUtc as localUtc,priceBeijing as beijing} from '../../services/price-policies.js'
import {imageRequestKey as createIdempotencyKey} from '../../services/private-images.js'
const fresh=()=>({priority:'',note:'',from:'',to:'',confirmed:false}),form=reactive(fresh()),selected=ref(null),editing=ref(0),revision=ref(0),sourcePage=ref(1),confirmation=ref(null),preview=ref(null),state=reactive(initialDiagnosisState()),api=createCurationApi()
const allowed=()=>operatorSession.canCommunityCurate,blocked=()=>state.busy||state.retry||state.kind==='storage'
let visible=false
function clearForm(){Object.assign(form,fresh());selected.value=null;editing.value=0;revision.value=0;preview.value=null}
async function load(t,p){const rows=await Promise.allSettled([api.list(t,p),api.sources(t,sourcePage.value)]);if(rows[0].status==='rejected')throw rows[0].reason;if(rows[1].status==='rejected'&&rows[1].reason.kind!=='unavailable')throw rows[1].reason;return {...rows[0].value,sources:rows[1].status==='fulfilled'?rows[1].value:null}}
const flow=createAsyncDiagnosisFlow({state,token:operatorToken,allowed,scope:()=>`curation:${operatorSession.actorId}`,load,write:(...args)=>api.write(...args),newKey:createIdempotencyKey,recovery:createCurationRecovery({actor:()=>operatorSession.actorId}),confirm:action=>new Promise(resolve=>{confirmation.value={action,resolve,snapshot:action==='discard-local'?null:preview.value?JSON.parse(JSON.stringify(preview.value)):null}}),onWritten:clearForm})
function resolveConfirm(ok){const c=confirmation.value;confirmation.value=null;c?.resolve(ok)}
function reset(){resolveConfirm(false);flow.reset();clearForm();sourcePage.value=1}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
function choose(s){if(blocked()||!state.data?.sources?.items.includes(s))return;selected.value=s;form.confirmed=false}
function edit(p){if(blocked()||p.status!=='DRAFT')return;editing.value=p.id;revision.value=p.revision;selected.value={experience:p.source_snapshot,source_hash:p.source_hash};Object.assign(form,{priority:String(p.priority),note:p.source_note,from:beijing(p.valid_from),to:beijing(p.valid_to),confirmed:false})}
function save(){if(blocked()||!selected.value||!state.data?.sources)return;const body={experience_id:selected.value.experience.experience_id,source_hash:selected.value.source_hash,priority:/^[1-9]\d{0,6}$/.test(form.priority)?Number(form.priority):0,source_note:form.note,scope_confirmed:form.confirmed,valid_from:localUtc(form.from),valid_to:localUtc(form.to),...(editing.value?{expected_revision:revision.value}:{})};if(!validCurationBody(body,editing.value?'update':'create')){state.message='请核对来源确认、正整数排序、来源说明及未来窗口';return}preview.value={...body,source_snapshot:selected.value.experience};flow.save(editing.value?'update':'create',editing.value,body)}
function status(p,to){if(blocked()||to==='PUBLISHED'&&!state.data?.sources)return;preview.value={...p,target_status:to};flow.save('status',p.id,{expected_revision:p.revision,status:to})}
function nextSource(delta){if(blocked())return;sourcePage.value+=delta;flow.load(state.page)}
watch(()=>[operatorSession.accessToken,allowed()],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
onShow(()=>{visible=true;if(operatorToken()&&allowed())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
</script>
<template><view class="reservation-page"><text class="reservation-title">同款经验运营精选</text><text>按获批经验版本、来源依据、排序和有效期配置。车主侧明确展示“运营精选”，不产生浏览热度。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><text v-else-if="!allowed()">当前账号没有独立精选权限。</text><template v-else><text v-if="state.busy" role="status">正在核对来源与配置…</text><text v-if="state.message" role="status">{{state.message}}</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button :disabled="state.busy" @tap="flow.load(state.page)">刷新配置与来源</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原精选请求</button><button v-if="state.kind==='storage'" :disabled="state.busy" @tap="flow.discardLocal">核对服务器并清理本机请求</button><template v-if="state.data"><text v-if="!state.data.sources">来源暂不可读取；可核对既有配置、停止或恢复原请求。</text><view v-else class="reservation-panel"><text class="reservation-heading">当前可核验的获批来源</text><text v-if="!state.data.sources.items.length">本页没有可核验的来源。</text><view v-for="s in state.data.sources.items" :key="s.experience.experience_id"><text>车型 {{s.experience.model_id}} · {{s.experience.summary.recorded_month}} · 工时 {{s.experience.summary.work_minutes}} 分钟</text><text>引用 {{s.experience.experience_id}}</text><button :disabled="blocked()" @tap="choose(s)">选择当前获批版本</button></view><button v-if="sourcePage>1" :disabled="blocked()" @tap="nextSource(-1)">上一页来源</button><button v-if="sourcePage*20<state.data.sources.total" :disabled="blocked()" @tap="nextSource(1)">下一页来源</button></view></template><view class="reservation-panel"><text class="reservation-heading">{{editing?'修改精选草稿':'新建精选草稿'}}</text><text v-if="selected">引用 {{selected.experience.experience_id}} · 车型 {{selected.experience.model_id}}</text><input v-model="form.priority" type="number" maxlength="7" :disabled="blocked()" placeholder="排序1至1000000，小值在前，同值新版在前"/><textarea v-model="form.note" maxlength="256" :disabled="blocked()" placeholder="仅运营可见的精选来源与排序依据"/><input v-model="form.from" maxlength="19" :disabled="blocked()" placeholder="北京时间生效 YYYY-MM-DD HH:mm:ss"/><input v-model="form.to" maxlength="19" :disabled="blocked()" placeholder="北京时间截止 YYYY-MM-DD HH:mm:ss"/><checkbox-group @change="form.confirmed=$event.detail.value.includes('confirmed')"><label><checkbox value="confirmed" :checked="form.confirmed" :disabled="blocked()"/>确认该获批版本、排序依据和有效期</label></checkbox-group><button :disabled="blocked()||!selected||!state.data?.sources" @tap="save">保存精选草稿</button><button :disabled="blocked()" @tap="clearForm">新建另一精选</button></view><template v-if="state.data"><view v-for="p in state.data.items" :key="p.id" class="reservation-panel"><text class="reservation-heading">{{p.status}} · 修订 {{p.revision}} · 排序 {{p.priority}}</text><text>引用 {{p.experience_id}} · 车型 {{p.source_snapshot.model_id}}</text><text>来源依据（仅运营）：{{p.source_note}}</text><text>北京时间 {{beijing(p.valid_from)}} 至 {{beijing(p.valid_to)}}（截止不含）</text><button v-if="p.status==='DRAFT'" :disabled="blocked()" @tap="edit(p)">修改并重新确认</button><button v-if="p.status==='DRAFT'" :disabled="blocked()||!state.data.sources" @tap="status(p,'PUBLISHED')">发布并冻结</button><button v-if="p.status==='PUBLISHED'" :disabled="blocked()" @tap="status(p,'STOPPED')">停止精选</button></view><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页精选</button><button v-if="state.page*20<state.data.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页精选</button></template><view v-if="confirmation" class="reservation-panel"><text class="reservation-heading">确认本次精选操作</text><template v-if="confirmation.snapshot"><text>引用 {{confirmation.snapshot.experience_id}} · 排序 {{confirmation.snapshot.priority}}</text><text>{{confirmation.snapshot.source_note}}</text><text>北京时间 {{beijing(confirmation.snapshot.valid_from)}} 至 {{beijing(confirmation.snapshot.valid_to)}}（截止不含）</text><text v-if="confirmation.snapshot.target_status">本次状态：{{confirmation.snapshot.target_status}} · 当前修订 {{confirmation.snapshot.revision}}</text></template><text v-else>请核对刚读取的服务器记录。本次仅清理本机未决请求，不删除服务器精选。</text><button @tap="resolveConfirm(true)">确认</button><button @tap="resolveConfirm(false)">取消</button></view></template><button @tap="uni.navigateTo({url:'/pages/operator/review'})">运营工作区</button></view></template>
